INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions, internal_category_id) VALUES ('1d62ac00-2ab8-5e44-b153-b949626e1851'::uuid, 'd82dedb5-3d26-5cfb-81c8-940ef81f045a'::uuid, 'Maîtrise d''œuvre architecturale — conception et suivi', 'Mission de professionnels BTP portée par BIARCHI, basé à Errachidia. BIARCHI est une entreprise / cabinet basé à Errachidia, spécialisé en Architect. Prestations sur devis pour particuliers et entreprises. La mission couvre typiquement les volets étude / accompagnement : Conseil et cadrage de la mission, Prestation adaptée au périmètre convenu, Expertise Architect, Suivi jusqu''à livraison de la mission. BIARCHI intervient à Errachidia, avec déplacement possible, pour particuliers et entreprises, en mission nationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées. Notre équipe accompagne le client de la définition du besoin jusqu''à la réalisation de la prestation architect, avec un interlocuteur dédié, un planning partagé et un reporting clair tout au long de la mission. Les options complémentaires (études, fournitures, suivi de chantier) sont proposées au cas par cas.', 'Architecture / Ingénierie', 'https://lechantier.ma/uploads/media/d9e9207b3de0.webp', '["https://lechantier.ma/uploads/media/d9e9207b3de0.webp"]'::jsonb, '["Étude", "Accompagnement"]'::jsonb, '["Conseil et cadrage de la mission", "Prestation adaptée au périmètre convenu", "Expertise Architect", "Suivi jusqu''à livraison de la mission"]'::jsonb, '["Options sur devis"]'::jsonb, 'devis', NULL, NULL, 'villes', '["Errachidia"]'::jsonb, NULL, TRUE, FALSE, '["Particuliers", "Entreprises"]'::jsonb, NULL, '["National"]'::jsonb, (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
