 livraison de la mission"]'::jsonb, '["Options sur devis"]'::jsonb, 'devis', NULL, NULL, 'villes', '["Casablanca"]'::jsonb, NULL, TRUE, FALSE, '["Particuliers", "Entreprises"]'::jsonb, NULL, '["National"]'::jsonb, (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
