INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions, internal_category_id) VALUES ('8eb6f2a2-6ce0-5524-a4f7-323a6edea849'::uuid, '7e4c36cf-d72a-5663-8ecc-04fcd5c41cd2'::uuid, 'Aluminium — offre clé en main', 'Mission de professionnels BTP portée par Abdessamad Elaamiri, basé à Marrakech. عندي 15 سنة ديال الخبرة في مجال تركيب الألومنيوم بجميع أنواعه: النوافذ، الأبواب، الواجهات، و المطابخ. كنركز على الدقة، الجودة، واحترام المواعيد. مستعد لإنجاز مشاريع كبيرة وصغيرة باحترافية عالية وضمان رضا الزبناء La mission couvre typiquement les volets réalisation / accompagnement : Conseil et cadrage de la mission, Prestation adaptée au périmètre convenu, Expertise Aluminium, Suivi jusqu''à livraison de la mission. Abdessamad Elaamiri intervient à Marrakech, avec déplacement possible, pour particuliers et entreprises, en mission nationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées. Notre équipe accompagne le client de la définition du besoin jusqu''à la réalisation de la prestation aluminium, avec un interlocuteur dédié, un planning partagé et un reporting clair tout au long de la mission. Les options complémentaires (études, fournitures, suivi de chantier) sont proposées au cas par cas.', 'Matériaux & équipements', 'https://lechantier.ma/logo.svg', '["https://lechantier.ma/uploads/media/dc0903442d16.webp", "https://lechantier.ma/uploads/media/67a62fafe62a.webp", "https://lechantier.ma/uploads/media/568c2536f33b.webp", "https://lechantier.ma/uploads/media/db7c5e7ede9e.webp", "https://lechantier.ma/logo.svg"]'::jsonb, '["Réalisation", "Accompagnement"]'::jsonb, '["Conseil et cadrage de la mission", "Prestation adaptée au périmètre convenu", "Expertise Aluminium", "Suivi jusqu''à livraison de la mission"]'::jsonb, '["Options sur devis"]'::jsonb, 'devis', NULL, NULL, 'villes', '["Marrakec