INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions, internal_category_id) VALUES ('6711f65c-d5ef-56c6-82c5-a14bf66a8107'::uuid, 'c34c4aa1-4017-5b75-9f86-2d0e969feff9'::uuid, 'Professionnel BTP — offre clé en main', 'Mission de professionnels BTP portée par Qarchi, basé à Casablanca. Vous avez un projet mais du mal à le visualiser ? Je transforme vos idées en rendus 3D réalistes, fidèles à vos envies. Que vous soyez architecte ou particulier, je vous aide à vous projeter clairement. Gagnez du temps, de la clarté et de l’impact… La mission couvre typiquement les volets réalisation / accompagnement : Conseil et cadrage de la mission, Prestation adaptée au périmètre convenu, Expertise Professionnel BTP, Suivi jusqu''à livraison de la mission. Qarchi intervient à Casablanca, avec déplacement possible, pour particuliers et entreprises, en mission nationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées. Notre équipe accompagne le client de la définition du besoin jusqu''à la réalisation de la prestation professionnel btp, avec un interlocuteur dédié, un planning partagé et un reporting clair tout au long de la mission. Les options complémentaires (études, fournitures, suivi de chantier) sont proposées au cas par cas.', 'Architecture / Ingénierie', 'https://lechantier.ma/uploads/media/9aae9559f6b6.webp', '["https://lechantier.ma/uploads/media/9aae9559f6b6.webp", "https://lechantier.ma/uploads/media/9ef2c0b91b6d.webp"]'::jsonb, '["Réalisation", "Accompagnement"]'::jsonb, '["Conseil et cadrage de la mission", "Prestation adaptée au périmètre convenu", "Expertise Professionnel BTP", "Suivi jusqu''à livraison de la mission"]'::jsonb, '["Options sur devis"]'::jsonb, 'devis', NULL, NULL, 'villes', '["Casablanca"]'::jsonb, NULL, TRUE, FALSE, '["Particuliers", "Entreprises"]'::jsonb, NULL, '["National"]'::jsonb, (SELECT id FROM public.internal_categories WHERE code = '5.4.4' LIMIT 1));
